mongodb:createCollection.mongodb:options:

{
    "validator": {
        "$jsonSchema": {
            "bsonType": "object",
            "required": ["order_id", "user_id", "status", "timestamp", "payment_amount"],
            "properties": {
                "order_id": {
                    "bsonType": "long",
                    "description": "The unique identifier of the order. Must be a long and is required."
                },
                "user_id": {
                    "bsonType": "long",
                    "description": "The unique identifier of the user. Must be a long and is required."
                },
                "status": {
                    "bsonType": "string",
                    "description": "The current status of the payment. Must be a string and is required."
                },
                "timestamp": {
                    "bsonType": "date",
                    "description": "The date and time when the payment occurred. Must be an ISODate and is required."
                },
                "payment_amount": {
                    "bsonType": "decimal",
                    "description": "The amount of money paid. Must be a precise decimal and is required."
                }
            }
        }
    }
}
